import request from '@/utils/request'


export function getCurrentUser() {
  return request({
    url: '/vip/me',
    method: 'get',
  })
}

export function logout() {
  return request({
    url: '/logout',
    method: 'post',
  })
}

export function login(data = {}) {
  return request({
    url: '/auth/login',
    method: 'post',
    data,
  })
}

export function editInfo(uuid, data = {}) {
  return request({
    url: `/vip/edit/${uuid}`,
    method: 'put',
    data
  })
}

export function getMyProducts(query) {
  return request({
    url: '/vip/products',
    method: 'get',
    params: query,
  })
}

export function applyCompany(data) {
  return request({
    url: '/vip/company/apply',
    method: 'post',
    data,
  })
}

export function getCompanyInfo(uid) {
  return request({
    url: `/vip/company/${uid}`,
    method: 'get'
  })
}

export function setCompanyIotConfig(id, data) {
  return request({
    url: `/vip/company/iot-config/${id}`,
    method: 'post',
    data,
  })
}

export function getCompanyIotConfig(id) {
  return request({
    url: `/vip/company/iot-config/${id}`,
    method: 'get'
  })
}

export function getCompanyIotApiList() {
  return request({
    url: '/vip/company/iot/apis',
    method: 'get',
  })
}

export function getCompanyIotApiGatewayList() {
  return request({
    url: '/vip/company/iot/gateways',
    method: 'get',
  })
}