import Cookies from 'js-cookie'
class Cache {
    constructor(useLocalStorage = false) {
        this.storage = useLocalStorage ? localStorage : Cookies
    }

    // eslint-disable-next-line no-unused-vars
    get(key) {
        return this.storage === localStorage 
            ? JSON.parse(this.storage.getItem(key))
            : this.storage.get(key)
    }

    set(key, value, options = {}) {
        if (this.storage === localStorage) {
            this.storage.setItem(key, JSON.stringify(value))
        } else {
            this.storage.set(key, value, options)
        }
    }

    setExpire(key, value, expires) {
        if (this.storage === localStorage) {
            this.storage.setItem(key, JSON.stringify(value))
        } else {
            this.storage.set(key, value, { expires: expires })
        }
    }

    remove(key) {
        if (this.storage === localStorage) {
            this.storage.removeItem(key)
        } else {
            this.storage.remove(key)
        }
    }

    exist(key) {
        if (this.storage === localStorage) {
            return this.storage.getItem(key) !== null
        }
        return this.storage.get(key) !== undefined
    }
}

export default Cache