import axios from 'axios'
import { Message } from 'element-ui'
import store from '@/store'
// eslint-disable-next-line no-unused-vars
import router from '@/router'
import { getToken } from '@/utils/auth'
import { openLoginDialog, closeLoginDialog } from '@/components/dialog/openLoginHandler'

// create an axios instance
const service = axios.create({
  baseURL: process.env.VUE_APP_API, // url = base url + request url
  // withCredentials: true, // send cookies when cross-domain requests
  timeout: 5000, // request timeout
})

// 创建一个取消令牌
const cancelTokenSource = axios.CancelToken.source()
let pendingRequests = [] // 存储待发送的请求

const removePending = (config) => {
  const index = pendingRequests.findIndex(request => {
    return request === config
  })
  if (index !== -1) {
    pendingRequests.splice(index, 1)
  }
}

// 取消所有待发送的请求
const cancelPendingRequests = () => {
  pendingRequests.forEach(request => {
    request.cancelToken.cancel('Request canceled due to 401 Unauthorized')
  })
  pendingRequests = []
}

// request interceptor
service.interceptors.request.use(
  (config) => {
    const href = window.location.href
    const url = new URL(href)
    if (url.pathname.includes('/vr')) {
      config.headers['X-Product-Code'] = url.pathname.replace('/vr/', '')
    }
    config.headers['X-Requested-With'] = 'XMLHttpRequest'
    if (store.getters.token) {
      config.headers['X-Auth-Token'] = getToken()
    }
    config.cancelToken = cancelTokenSource.token
    pendingRequests.push(config)
    return config
  },
  (error) => {
    return Promise.reject(error)
  }
)

// response interceptor
service.interceptors.response.use(
  (response) => {
    removePending(response.config)
    const res = response.data
    if (res.code !== 0) {
      Message({
        message: res.message || 'Error',
        type: 'error',
        duration: 5 * 1000,
      })
      return Promise.reject(new Error(res.message || 'Error'))
    } else {
      return res.data
    }
  },
  (error) => {
    removePending(error.config)
    const errorResponse = error.response
    const status = errorResponse.status
    if (errorResponse && 'data' in errorResponse && errorResponse.data) {
      // eslint-disable-next-line no-unused-vars
      const { code, message } = errorResponse.data
      Message({
        message: message,
        type: 'error',
        duration: 5 * 1000,
      })
      if (status === 401) {
        store.dispatch('user/resetToken').then(() => {
          // cancelTokenSource.cancel('Request canceled due to 401 Unauthorized')
          cancelPendingRequests()
          openLoginDialog(store.getters.systemTitle, 'login', {
            onSubmit() {
              console.log('点了确定按钮')
            },
            onCancel() {
              console.log('点了取消按钮')
            },
          })
        })
      } else if (status === 403) {
        closeLoginDialog()
        if (process.env.VUE_APP_DEBUG == 1) {
          return router.replace({
            path: '/403',
          })
        }
      } else if (status === 404) {
        closeLoginDialog()
        if (process.env.VUE_APP_DEBUG == 1) {
          return router.replace({
            path: '/404',
          })
        }
      } else if (status === 500) {
        closeLoginDialog()
        if (process.env.VUE_APP_DEBUG == 1) {
          return router.replace({
            path: '/500',
          })
        }
      }
    } else {
      Message({
        message: error.message,
        type: 'error',
        duration: 5 * 1000,
      })
    }

    return Promise.reject(error)
  }
)

export default service
