<template>
  <el-container v-loading="loading" class="center-product">
    <el-header class="home-header" v-if="!isSSOLogin">
      <vr-header />
    </el-header>
    <el-container class="home-body">
      <div class="home-box">
        <el-row v-if="token">
          <div class="panel panel-default panel-page panel-create-vr">
            <div class="panel-heading">
              <div class="flex-item">
                <h2>创建作品</h2>
                <div class="action-back" v-if="isSSOLogin">
                  <el-button type="primary" @click="jumpProuducts" size="mini"
                    >作品管理</el-button
                  >
                </div>
              </div>
            </div>
            <div class="panel-body">
              <el-form :model="form" ref="productForm" :rules="rules">
                <el-form-item>
                  <div class="vr-piece">作品类型</div>
                  <el-row :gutter="24">
                    <el-col
                      :span="8"
                      v-for="(item, index) in productTypeItems"
                      :key="index"
                    >
                      <div
                        class="type-select"
                        :class="item.key === form.type ? 'active' : ''"
                        @click.stop="onChangeType(item.key)"
                      >
                        <el-image class="vr-img" :src="item.logo" />
                        <div class="vr-type">{{ item.label }}</div>
                        <div class="vr-intro">
                          {{ item.desc }}
                        </div>
                      </div>
                    </el-col>
                  </el-row>
                </el-form-item>
                <el-form-item prop="title">
                  <div class="vr-piece">作品名称</div>
                  <el-input v-model="form.title"></el-input>
                </el-form-item>
                <el-form-item v-if="'pictures' === form.type" prop="scenes">
                  <div class="vr-piece">添加场景图</div>
                  <div class="vr-scene-list" v-if="form.scenes">
                    <el-image
                      v-for="(scene, index) in form.scenes"
                      :key="index"
                      :src="scene.thumb_url ? scene.thumb_url : scene.url"
                      :preview-src-list="previewSceneSrcList"
                      lazy
                    ></el-image>
                  </div>
                  <div class="vr-scene-ctrl" v-if="form.scenes.length < 5">
                    <div class="vr-scene-btn" @click.stop="addScene">
                      从本地文件添加
                    </div>
                    <div class="el-upload__tip">
                      支持 2:1全景图片素材;最大支持30m以内的全景图
                    </div>
                  </div>
                </el-form-item>
                <el-form-item>
                  <div class="text-center">
                    <el-button type="primary" @click="onSave" class="save-btn"
                      >创建</el-button
                    >
                    <el-button @click="resetForm">重置</el-button>
                  </div>
                </el-form-item>
              </el-form>
            </div>
          </div>
        </el-row>
        <el-empty v-else :image="companyBanner"></el-empty>
      </div>
    </el-container>
    <scene-img-form-dialog
      ref="sceneImgDialog"
      uploadClass="upload-scene-img"
      scene="saveAndAdd"
      @ok="onAfterAddScene"
    />
  </el-container>
</template>

<script>
import { mapGetters } from 'vuex'
import { getProductTypeItems, createProduct } from '@/api/vr'
const defaultQuery = {
  keyword: '',
  page_current: 1,
  page_size: 10,
}
const defaultForm = {
  title: '',
  catalogId: undefined,
  type: 'pictures',
  recommendTagIds: [],
  customTags: '',
  scenes: [],
}
export default {
  name: 'HomeIndex',
  components: {
    VrHeader: () => import('./layout/header.vue'),
    SceneImgFormDialog: () => import('./form/SceneImgFormDialog.vue'),
  },
  data() {
    return {
      query: Object.assign({}, defaultQuery),
      loading: false,
      form: Object.assign({}, defaultForm),
      productTypeItems: [],
      companyBanner:
        'https://image.xiangyike.com/images/index/wrapper_img1.png',
      rules: {
        title: [
          { required: true, message: '请输入作品名称', trigger: 'blur' },
          {
            min: 1,
            max: 100,
            message: '长度在 1 到 100 个字符',
            trigger: 'blur',
          },
        ],
        scenes: [
          {
            type: 'array',
            required: true,
            message: '请至少添加一张全景场景图',
            trigger: 'change',
          },
        ],
      },
    }
  },
  computed: {
    ...mapGetters(['systemTitle', 'token']),
    isSSOLogin() {
      return parseInt(this.$cache.get('sso_auth')) === 1
    },
    previewSceneSrcList() {
      return this.form.scenes.map((item) => {
        return item.thumb_url ? item.thumb_url : item.url
      })
    },
  },
  created() {
    this.getProductTypeItems()
  },
  mounted() {},
  beforeRouteEnter(to, from, next) {
    next((vm) => {
      vm.resetForm()
    })
  },
  beforeDestroy() {
    this.resetForm()
  },
  methods: {
    async getProductTypeItems() {
      this.productTypeItems = await getProductTypeItems()
    },
    onChangeType(type) {
      if (type !== 'pictures') {
        return false
      }
      this.form.type = type
    },
    addScene() {
      this.$refs.sceneImgDialog.open()
    },
    onAfterAddScene(result) {
      // console.log('res:', result)
      this.form.scenes.push(result)
    },
    onSave() {
      this.$refs.productForm.validate((valid) => {
        if (valid) {
          // eslint-disable-next-line no-unused-vars
          createProduct(this.form).then((result) => {
            // console.log('dd:', result)
            this.$message.success('创建成功，进入装修中心')
            // this.form.scenes = []
            // this.$set(this.form, 'scenes', [])
            // console.log('this.form:', this.form)
            // this.form = Object.assign({}, defaultForm)
            this.resetForm()
            this.jumpDIY(result.id)
          })
        } else {
          console.log('error submit!!')
          return false
        }
      })
    },
    resetForm() {
      this.form = Object.assign({}, defaultForm)
      this.$set(this.form, 'scenes', [])
      this.$refs.productForm.resetFields()
      this.$refs.productForm.clearValidate()
    },
    // 跳转预览页
    jumpShow(product) {
      if (product.status !== 'published') {
        return false
      }
      let routeUrl = this.$router.resolve({
        path: `/view/${product.id}`,
      })
      window.open(routeUrl.href, '_blank')
    },
    jumpProuducts() {
      this.$router.push('/vip/products')
    },
    // 跳转装修页
    jumpDIY(id) {
      this.$router.replace(`/diy/${id}`)
    },
  },
}
</script>
