// import Cookies from 'js-cookie'
import Cache from './cache'
import { isHexUUID, isValidJWT, isInIframe } from './tools'

const TokenKey = process.env.VUE_APP_AUTH_TKEN || 'diy_vr_frontend_token'
const authCache = new Cache(!isInIframe())

export function getToken() {
  const urlParams = new URLSearchParams(window.location.search)
  const token = urlParams.get('token') || null
  if (token && (isHexUUID(token) || isValidJWT(token))) {
    setToken(token)

    return token
  }

  return authCache.get(TokenKey)
}

export function setToken(tokenRaw, expires = 7) {
  return authCache.set(TokenKey, parseTokenRaw(tokenRaw), { expires: expires })
}

export function removeToken() {
  authCache.remove(TokenKey)
  authCache.remove('sso_auth')
  authCache.remove('currentToolbarCode')
  return true
}

export function parseTokenRaw(tokenRaw) {
  if (!tokenRaw) {
    return ''
  }

  if (typeof tokenRaw === 'string') {
    return tokenRaw
  }

  const { token, token_type } = tokenRaw
  if (!token_type) {
    return token
  }

  return token_type + ' ' + token
}
