import Dialog from './LoginDialog'
import Vue from 'vue'
let $vm, dialogConstructor

export function openLoginDialog(title, type, cbs) {
  if (!dialogConstructor) {
    dialogConstructor = Vue.extend(Dialog)
  }
  if (!$vm) {
    $vm = new dialogConstructor()
  }
  $vm.$mount().open(title, type, cbs)
}

export function closeLoginDialog() {
  if ($vm) {
    $vm.$destroy() // 销毁 Vue 实例
    $vm.$el.remove() // 移除对应的 DOM 元素
    $vm = null // 重置 $vm 为 null
  }
}
