/* eslint-disable no-unused-vars */
import { logout, getCurrentUser } from '@/api/user'
import { getToken, setToken, removeToken, parseTokenRaw } from '@/utils/auth'
import { resetRouter } from '@/router'

const getDefaultState = () => {
  return {
    token: getToken(),
    nickname: '',
    avatar: '',
    avatar_full: '',
    intro: '',
    uuid: '',
    id: undefined,
    company_banner_cover: ''
  }
}

const state = getDefaultState()

const mutations = {
  RESET_STATE: (state) => {
    Object.assign(state, getDefaultState())
  },
  SET_TOKEN: (state, token) => {
    state.token = parseTokenRaw(token)
  },
  SET_NICKNAME: (state, name) => {
    state.name = name
  },
  SET_AVATAR: (state, avatar) => {
    state.avatar = avatar
  },
  SET_AVATAR_FULL: (state, avatar_full) => {
    state.avatar_full = avatar_full
  },
  SET_INTRO: (state, intro) => {
    state.intro = intro
  },
  SET_UUID: (state, uuid) => {
    state.uuid = uuid
  },
  SET_ID: (state, id) => {
    state.id = id
  },
  SET_COMPANY_BANNER_COVER: (state, companyBannerCover) => {
    state.companyBannerCover = companyBannerCover
  }
}

const actions = {
  // user logout
  logout({ commit }) {
    return new Promise((resolve, reject) => {
      // removeToken() // must remove  token  first
      // resetRouter()
      // commit('RESET_STATE')
      // resolve()
      logout()
        .then(() => {
          removeToken() // must remove  token  first
          resetRouter()
          commit('RESET_STATE')
          commit('SET_TOKEN', null)
          resolve()
        })
        .catch((error) => {
          reject(error)
        })
    })
  },

  // remove token
  resetToken({ commit }) {
    return new Promise((resolve) => {
      commit('SET_TOKEN', null)
      removeToken() // must remove  token  first
      commit('RESET_STATE')
      resolve()
    })
  },
  login({ commit }, user) {
    return new Promise((resolve) => {
      removeToken()
      commit('SET_NICKNAME', user.nickname)
      commit('SET_AVATAR', user.avatar)
      commit('SET_AVATAR_FULL', user.avatar_full)
      commit('SET_INTRO', user.intro)
      commit('SET_TOKEN', user.token)
      commit('SET_UUID', user.uuid)
      commit('SET_ID', user.id)
      setToken(user.token)
      resolve()
    })
  },
  getCurrentUser({ commit }) {
    return new Promise((resolve) => {
      getCurrentUser().then(res => {
        commit('SET_NICKNAME', res.nickname)
        commit('SET_AVATAR', res.avatar)
        commit('SET_AVATAR_FULL', res.avatar_full)
        commit('SET_INTRO', res.intro)
        commit('SET_UUID', res.uuid)
        commit('SET_ID', res.id)
        commit('SET_COMPANY_BANNER_COVER', res.company_banner_cover)
        resolve()
      })
    })
  }
}

export default {
  namespaced: true,
  state,
  mutations,
  actions,
}
