<!-- eslint-disable no-unused-vars -->
<template>
  <div>
    <el-dialog
      :title="title"
      :visible.sync="dialogVisible"
      :destroy-on-close="true"
      :close-on-click-modal="false"
      :close-on-press-escape="false"
      :show-close="false"
      width="300px"
      :center="true"
      :append-to-body="true"
      class="login-reg-dialog"
    >
      <el-form
        :model="model"
        status-icon
        :rules="rules"
        :ref="formName"
        class="handle-dialog-form"
      >
        <el-form-item prop="username">
          <el-input
            type="text"
            v-model="model.username"
            autocomplete="off"
            placeholder="请输入用户名"
            size="medium"
          >
            <i slot="prefix" class="el-input__icon el-icon-user"></i>
          </el-input>
        </el-form-item>
        <el-form-item prop="password">
          <el-input
            type="password"
            v-model="model.password"
            autocomplete="off"
            placeholder="请输入密码"
            size="medium"
          >
            <i slot="prefix" class="el-input__icon el-icon-lock"></i>
          </el-input>
        </el-form-item>
        <!-- <el-form-item prop="read_arg">
          <el-radio v-model="model.read_arg" label="1">
            <el-link
              type="primary"
              :underline="false"
              href="https://www.boyuntong.com"
              target="_blank"
              >请先阅读《用户协议》</el-link
            ></el-radio
          >
        </el-form-item> -->
      </el-form>
      <span slot="footer" class="dialog-footer">
        <el-button
          type="primary"
          @click="login"
          size="small"
          v-if="type === 'login'"
          :loading="btnLoading"
          >登 录</el-button
        >
      </span>
    </el-dialog>
  </div>
</template>

<script>
// eslint-disable-next-line no-unused-vars
import { login } from '@/api/user'
import store from '@/store'
const defaultModel = {
  username: '',
  password: '',
  read_arg: true,
}

export default {
  name: 'LoginDialog',
  props: {},
  data() {
    return {
      isOpenFlag: false,
      dialogVisible: false,
      title: '',
      type: 'login',
      model: Object.assign({}, defaultModel),
      btnLoading: false,
    }
  },
  computed: {
    formName() {
      return `${this.type}HandleForm`
    },
    rules() {
      const validateReadArg = (_rule, value, callback) => {
        if (value === false) {
          callback(new Error('请先勾选用户协议'))
        } else {
          callback()
        }
      }
      const rules = {
        username: [
          { required: true, message: '请输入用户名', trigger: 'blur' },
          {
            min: 3,
            max: 20,
            message: '长度在 3 到 20 个字符',
            trigger: 'blur',
          },
        ],
        password: [
          { required: true, message: '请输入密码', trigger: 'blur' },
          {
            min: 6,
            max: 10,
            message: '长度在 6 到 10 个字符',
            trigger: 'blur',
          },
        ],
        read_arg: [{ validator: validateReadArg, trigger: 'blur' }],
      }

      return rules
    },
  },
  methods: {
    showLoginForm() {
      this.type = 'login'
      this.reset()
    },
    showRegisterForm() {
      this.type = 'register'
      this.reset()
    },
    open(title, type, cbs = {}) {
      this.title = title
      this.type = type
      this.dialogVisible = true
      this.cbs = cbs
      this.isOpenFlag = true
    },
    getQueryParam(name) {
      const urlParams = new URLSearchParams(window.location.search)
      return urlParams.get(name)
    },
    login() {
      // 处理登录
      this.btnLoading = true
      this.$refs[`${this.formName}`].validate((valid, errs) => {
        if (valid) {
          login(this.model)
            .then(async (result) => {
              await store.dispatch('user/login', result)
              setTimeout(() => {
                const ssoToken = this.getQueryParam('itoken')
                if (ssoToken) {
                  try {
                    this.$router.push('/vip/products')
                  } catch (error) {
                    location.href = '/vip/products'
                  }
                } else {
                  location.reload()
                }
              }, 1000)
            })
            // eslint-disable-next-line no-unused-vars
            .catch((_err) => {
              setTimeout(() => {
                this.btnLoading = false
              }, 1000)
              // this.$message.error(_err.message)
            })
        } else {
          setTimeout(() => {
            this.btnLoading = false
          }, 1500)
          for (const key in errs) {
            this.$message.error(errs[key][0].message)
            return false
          }
        }
      })
      this.afterHock()
      //this.reset()
    },
    afterHock(method = 'onSubmit') {
      if (
        Object.prototype.toString.call(this.cbs[method]) === '[object Function]'
      ) {
        this.cbs[method]()
      }
      // if (
      //   Object.prototype.toString.call(this.cbs['onCannel']) ===
      //   '[object Function]'
      // ) {
      //   this.cbs['onCannel']()
      // }
    },
    onCancel() {
      this.dialogVisible = false
      this.isOpenFlag = false
      this.reset()
    },
    reset() {
      this.$nextTick(() => {
        this.$refs[`${this.formName}`].resetFields()
        this.$refs[`${this.formName}`].clearValidate()
      })
      this.model = Object.assign({}, defaultModel)
    },
  },
}
</script>
